function defenseResult(){const a=modifiedResults(),d=attackState.defense,p=effectiveDefenseProfile(defender),duelistAttack=allResolved(attacker).some(x=>x.def.id==='duelliste')?engine.duelistModifiers({melee:attackType()==='melee',aimSpent:attackState.aims}):{pierceBonus:0},lethal=engine.applyLethal(attackKeywordValue('perforant-x')+duelistAttack.pierceBonus,attackKeywordValue('letal-x'),attackState.lethalAims),guardian=guardianContext(),pierceX=guardian.result.pierceRemaining,pierceImmunePrinted=allResolved(defender).some(x=>x.def.id==='immunite-perforant'||(x.def.id==='immunite-perforant-corps-a-corps'&&attackType()==='melee')),dodgesUsed=afterCover().dodgesUsed,duelistDefense=allResolved(defender).some(x=>x.def.id==='duelliste')?engine.duelistModifiers({melee:attackType()==='melee',dodgeSpent:dodgesUsed}):{pierceImmune:false},pierceImmune=pierceImmunePrinted||duelistDefense.pierceImmune,blockActive=keywordValue(defender,'blocage')>0&&dodgesUsed>0,holdFast=attackState.engaged&&allResolved(defender).some(x=>x.def.id==='tenir-bon'),missionDefense=attackState.priorityMissionDefense&&allResolved(defender).some(x=>x.def.id==='accomplir-la-mission'),defenseSurge=holdFast||missionDefense?'block':engine.effectiveDefenseSurge(p?.defenseSurge,blockActive,dodgesUsed);return {a,d,p,lethal,guardian,pierceX,pierceImmune,dodgesUsed,blockActive,holdFast,missionDefense,defenseSurge,duelistAttack,duelistDefense,result:engine.applyDefense(a,d,{defenseSurge,pierceX,pierceImmune})}}
function liveDefenseStrip(result){return `<div class="result-strip live-defense-strip" aria-live="polite"><b>APRÈS DÉFENSE</b><b><span data-live-blocks>${result.blocks}</span> blocage(s)</b><b class="final-wounds"><i class="blood-drop" aria-hidden="true"></i><span data-live-wounds>${result.wounds}</span> blessure(s)</b></div>`}
function inputWarning(){const issue=stepIssue();return `<div class="strict-warning input-warning" role="alert" ${issue?'':'hidden'}>⚠ <span>${issue||''}</span></div>`}
function updateInputWarning(){const warning=root.querySelector('.input-warning');if(!warning)return;const issue=stepIssue();warning.hidden=!issue;warning.querySelector('span').textContent=issue||''}
/* Rejoue une brève animation d'éclat (sw-effects.css) sur un élément dont le
   texte vient d'être patché sans que le nœud lui-même soit recréé — une
   simple classe CSS ne se rejouerait pas d'elle-même : on la retire puis la
   repose après un reflow forcé (void el.offsetWidth) pour forcer le
   redémarrage. cls par défaut 'wound-pulse' pour ne rien changer aux appels
   existants ; réutilisé aussi pour les éclats « refusé » ci-dessous. */
function pulseEl(el,cls='wound-pulse'){if(!el)return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls)}
function effectiveAttackProfile(){const certified=profileFor(attacker.unit.name),printed=combatProfiles[cardKey(attacker.unit.name)]||certified,weaponConversions=selectedWeaponRows().map(row=>row.weapon.attackSurge).filter(Boolean),attackSurge=weaponConversions.includes('crit')?'crit':weaponConversions.includes('hit')?'hit':printed?.attackSurge,source=weaponConversions.length?'Conversion accordée par une arme de la réserve':printed?.source||printed?.verificationSource;return {...printed,attackSurge,source,verified:printed?.verified!==false}}
function updateLiveCounters(){const progress=root.querySelector('[data-entry-progress]');if(progress){const kind=progress.dataset.entryProgress,wasComplete=progress.classList.contains('complete'),holder=document.createElement('div');holder.innerHTML=entryProgress(kind);const fresh=holder.firstElementChild;if(fresh.classList.contains('complete')&&!wasComplete)fresh.classList.add('progress-complete-pop');progress.replaceWith(fresh)}const strip=root.querySelector('.live-result-strip');if(strip){const results=attackStep===1?attackResults():attackStep===2?afterCover():attackStep===3?modifiedResults():null;if(results){strip.querySelector('[data-live-hit]').textContent=results.hit;strip.querySelector('[data-live-crit]').textContent=results.crit}}const defenseStrip=root.querySelector('.live-defense-strip');if(defenseStrip){const {result}=defenseResult();defenseStrip.querySelector('[data-live-blocks]').textContent=result.blocks;defenseStrip.querySelector('[data-live-wounds]').textContent=result.wounds;if(result.wounds>0)pulseEl(defenseStrip.querySelector('.final-wounds'));const total=root.querySelector('[data-live-total-wounds]');if(total){total.textContent=result.wounds;if(result.wounds>0)pulseEl(total.closest('.total'))}}const journey=root.querySelector('.dice-journey');if(journey){const holder=document.createElement('div');holder.innerHTML=diceJourney();journey.replaceWith(holder.firstElementChild)}if(attackStep===1){const p=effectiveAttackProfile(),precise=attackKeywordValue('precis-x'),capacity=engine.rerollCapacity(attackState.aims,precise),lethalX=attackKeywordValue('letal-x'),lethal=engine.applyLethal(attackKeywordValue('perforant-x'),lethalX,attackState.lethalAims),critical=attackKeywordValue('critique-x'),converted=engine.convertAttack(attackState.roll,p?.attackSurge,critical),conversion=root.querySelector('.roll-conversion-panel'),rerolls=root.querySelector('.roll-reroll-panel');if(conversion)conversion.outerHTML=rollConversionPanel(p,converted,critical);if(rerolls)rerolls.outerHTML=rollRerollPanel(capacity,precise,lethalX,lethal,converted)}updateInputWarning()}
function bindLiveCounters(){root.querySelectorAll('#aims,#lethalAims,#rerolled,#rollHit,#rollCrit,#rollSurge,#rollBlank,#activeShields,#shieldHit,#shieldCrit,#guardianHits,#guardianBlock,#guardianSurge,#guardianBlank,#impact,#armor,#coverBlock,#coverSurge,#dodges,#defBlock,#defSurge,#defBlank').forEach(input=>input.addEventListener('input',()=>{pulseEl(input.closest('.quick-field'),'field-touched');updateLiveCounters()}))}
function activeAttackTags(){const resolved=allResolved(attacker),unitRules=resolved.filter(x=>displayImpacts(x).includes('attaque')&&x.def.category!=='arme'),weaponRules=selectedWeaponRows().flatMap(row=>definitionsFor(row.card).filter(x=>displayImpacts(x).includes('attaque')&&x.def.category==='arme'&&weaponHasKeyword(row,x.def.id)).map(x=>({...x,tag:{...x.tag,value:row.weapon.keywordValues?.[x.def.id]??x.tag.value}}))),reluctant=(attacker?.unit?.upgrades||[]).find(upgrade=>profileFor(upgrade.name)?.criticalPerSuppression),criticalDef=keywords.find(def=>def.id==='critique-x'),conditional=reluctant&&criticalDef?[{source:reluctant.name,def:criticalDef,tag:{keywordId:'critique-x',value:stateFor(attacker).suppression}}]:[];return [...unitRules,...weaponRules,...conditional]}
function ambiguousWeaponRules(){return selectedWeaponRows().flatMap(row=>{const profile=profileFor(row.card),weaponRules=definitionsFor(row.card).filter(x=>x.def.category==='arme'&&displayImpacts(x).includes('attaque'));if((profile?.weapons?.length||0)<2||!weaponRules.length||Array.isArray(row.weapon.keywordIds))return[];return [{card:displayName(row.card),weapon:row.weapon.name,rules:weaponRules.map(x=>x.def.name).join(', ')}]})}
function relevantKeywords(){const seen=new Set;return [...activeAttackTags(),...allResolved(defender).filter(x=>displayImpacts(x).includes('défense'))].filter(x=>!seen.has(`${x.def.id}:${x.source}`)&&seen.add(`${x.def.id}:${x.source}`))}
function rulesPanel(){const rows=relevantKeywords(),ambiguous=ambiguousWeaponRules();return `${ambiguous.length?`<div class="strict-warning" role="alert">⚠ Association arme/règle à vérifier : ${ambiguous.map(x=>`${x.weapon} (${x.card}) — ${x.rules}`).join(' ; ')}. Ces effets ne sont pas calculés tant qu’ils ne sont pas rattachés à cette arme dans le référentiel.</div>`:''}<details class="rules-panel" ${quickMode?'':'open'}><summary>Règles qui interviennent (${rows.length})${quickMode?' · toucher pour le détail':''}</summary>${rows.length?rows.map(x=>`<article><b>${x.def.name}${x.tag.value!=null?' '+x.tag.value:''}</b><small>${definitionText(x)} · ${displayName(x.source)}</small></article>`).join(''):'<p>Aucun mot-clé d’attaque ou de défense rattaché.</p>'}</details>`}
function sideSurge(entry,side){const p=side==='defense'?effectiveDefenseProfile(entry):{...profileFor(entry.unit.name),...combatProfiles[cardKey(entry.unit.name)]},type=side==='attack'?'attack':'defense',value=type==='attack'?p?.attackSurge:p?.defenseSurge,label=type==='attack'?'ADRÉNALINE D’ATTAQUE':'ADRÉNALINE DE DÉFENSE';return `<div class="side-surge"><small>${label}</small>${surgeResult(type,value)}<em>${value==='hit'?'vers Touche':value==='crit'?'vers Critique':value==='block'?'vers Blocage':'aucune conversion'}</em></div>`}
function defenseVerification(entry){const profile=profileFor(entry.unit.name);if(!profile?.defenseColor)return'';const verified=profile.defenseVerifiedAgainstCard;return `<div class="defense-verification ${verified?'verified':'unverified'}" title="${(profile.defenseVerificationSource||'Couleur de défense à comparer à la carte source.').replace(/"/g,'&quot;')}">${verified?'✓ Dé de défense vérifié':'⚠ Dé de défense non certifié'}</div>`}
function sideStatusHud(entry){const state=stateFor(entry),stats=certifiedUnitStats(entry),immune=moraleImmune(entry),isLiveDefender=entry===defender&&attackState,wounds=isLiveDefender?attackState.currentWounds+(attackStep>=4?defenseResult().result.wounds:0):state.wounds;let suppression=immune?0:(isLiveDefender?attackState.currentSuppression:state.suppression);if(isLiveDefender&&attackStep>=5){const ranged=attackType()==='ranged',hadResult=attackResults().hit+attackResults().crit>0,suppressive=activeAttackTags().some(x=>x.def.id==='suppressif'),overwhelm=activeAttackTags().some(x=>x.def.id==='debordement');suppression=engine.moraleState({currentSuppression:attackState.currentSuppression,gainedSuppression:engine.suppressionTokens({ranged,hadAttackResult:hadResult,suppressive,overwhelm,aimSpent:attackState.aims>0,vehicle:isVehicle(defender)}),courage:attackState.defenderCourage,commanderCourage:attackState.commanderCourage,nullCourage:attackState.nullCourage,vehicle:isVehicle(defender)}).total}let woundBudget=wounds,remaining=stats?.totalModels??null;if(stats){remaining=0;for(const model of stats.models){const applied=Math.min(model.maxWounds,woundBudget);woundBudget-=applied;if(applied<model.maxWounds)remaining++}}return `<div class="side-status" aria-label="État de l’unité"><span><small>FIGURINES</small><b>${remaining??'?'}${stats?`/${stats.totalModels}`:''}</b></span><span><small>BLESSURES</small><b><i class="blood-drop" aria-hidden="true"></i>${wounds}</b></span><span class="${immune?'suppression-immune':''}"><small>SUPPRESSION</small><b>${immune?'—':suppression}</b></span></div>`}
const collapsedSides={attack:false,defense:false};
function combatAside(entry,side){return `<aside class="combat-side ${side} ${collapsedSides[side]?'collapsed':''}"><button class="side-collapse" data-collapse-side="${side}" aria-label="${collapsedSides[side]?'Déplier':'Replier'} la colonne">${collapsedSides[side]?'›':'‹'}</button><div class="side-detail">${unitVisual(entry,side)}${sideStatusHud(entry)}<div class="mini-upgrades">${(entry.unit.upgrades||[]).map(u=>`<button class="upgrade-visual" data-card-name="${displayName(u.name).replace(/"/g,'&quot;')}" data-card-image="${imageFor(u.name)}" aria-label="Voir la carte ${displayName(u.name).replace(/"/g,'&quot;')}"><img src="${imageFor(u.name)}" alt=""><span aria-hidden="true">+</span></button>`).join('')||'<small>Sans amélioration</small>'}</div>${sideSurge(entry,side)}</div></aside>`}
function resultMarker(id){const icons={rollHit:'hit',rollCrit:'crit',rollSurge:'attackSurge',defBlock:'block',defSurge:'defenseSurge',coverBlock:'block',coverSurge:'defenseSurge'};return icons[id]?diceIcon(icons[id],'large'):/Blank$/.test(id)?'<span class="blank-die" aria-label="Face vierge"></span>':''}
function numberField(id,label,value,max='99'){const current=Math.max(0,Number(value)||0),limit=Math.max(0,Number(max)||0);return `<div class="quick-field">${resultMarker(id)}<span class="quick-label">${label}</span><div class="touch-counter"><button type="button" data-adjust="${id}" data-delta="-1" aria-label="Diminuer" ${current<=0?'disabled':''}>−</button><input id="${id}" aria-label="${id}" type="number" inputmode="numeric" min="0" max="${limit}" value="${current}"><button type="button" data-adjust="${id}" data-delta="1" aria-label="Augmenter" ${current>=limit?'disabled':''}>+</button></div></div>`}
function entryProgress(kind){const values=kind==='attack'?attackState.roll:attackState.defense,total=Object.values(values).reduce((sum,value)=>sum+(Number(value)||0),0),expected=kind==='attack'?(()=>{const p=pool();return p.rouge+p.noir+p.blanc})():(modifiedResults().hit+modifiedResults().crit),complete=total===expected;return `<div class="entry-progress ${complete?'complete':total>expected?'over':'pending'}" data-entry-progress="${kind}"><span>${complete?'✓':'↻'}</span><strong>${total} / ${expected} dés saisis</strong><small>${complete?'Saisie complète':total>expected?'Trop de résultats saisis':'Continuez la saisie des faces obtenues'}</small></div>`}
