function coverScreen(){const a=attackResults(),c=afterCover(),ctx=coverContext(),dodgeCritsAllowed=allResolved(defender).some(x=>x.def.id==='manoeuvre-improbable'),diceToRoll=Math.max(0,a.hit-(ctx.profileLow?1:0)),coverReason=ctx.indifferent?'Indifférent interdit à cette unité de bénéficier d’un couvert.':ctx.deathFromAbove?'La Mort venue du ciel ignore le couvert dans cette situation.':ctx.blast&&!ctx.immuneBlast?'Déflagration ignore le couvert.':ctx.sharpshooter?`Tireur d’élite ${ctx.sharpshooter} réduit le couvert de ${ctx.sharpshooter}.`:'Aucune réduction automatique.',coverDice=ctx.effective==='none'?'<div class="no-cover-notice">Aucun dé de couvert à lancer : aucune touche ne peut être annulée par le couvert.</div>':`${ctx.profileLow?`<div class="automation-card rule-highlight"><strong>PROFIL BAS : ${diceIcon('block')} 1 AUTOMATIQUE</strong><small>Lancez ${diceToRoll} dé(s) de couvert au lieu de ${a.hit}. Un dé a été remplacé par ce blocage.</small></div>`:`<div class="automation-card"><strong>LANCEZ ${diceToRoll} DÉ(S) DE COUVERT</strong></div>`}${numberField('coverBlock',`${diceIcon('block')} obtenus sur les dés lancés`,attackState.coverBlock,diceToRoll)}${ctx.effective==='heavy'?numberField('coverSurge',`${diceIcon('defenseSurge')} obtenues sur les dés lancés`,attackState.coverSurge,diceToRoll):''}`;return `<div class="result-strip"><b>${diceIcon('hit','large')} ${a.hit}</b><b>${diceIcon('crit','large')} ${a.crit}</b></div><h2>3. Appliquer couvert et esquives</h2><p class="step-help">Sélectionnez le couvert observé sur la table. L’assistant applique les règles de couvert, puis les esquives avant toute modification ultérieure des dés d’attaque.</p>${ctx.deathFromAboveAvailable?`<label class="situation-check"><input id="deathFromAbove" type="checkbox" ${attackState.deathFromAbove?'checked':''}> Le chef attaquant est sur un terrain hors zone plus élevé que le chef défenseur</label>`:''}<div class="cover-options"><button data-cover="none" class="${attackState.cover==='none'?'on':''}">Aucun</button><button data-cover="light" class="${attackState.cover==='light'?'on':''}">Léger</button><button data-cover="heavy" class="${attackState.cover==='heavy'?'on':''}">Lourd</button></div><div class="automation-card rule-highlight cover-${ctx.effective}"><strong>COUVERT EFFECTIF : ${ctx.effective==='heavy'?'LOURD':ctx.effective==='light'?'LÉGER':'AUCUN'}</strong><small>${coverReason}</small>${ctx.highVelocity?'<strong>HAUTE VÉLOCITÉ : ESQUIVES INTERDITES</strong>':''}</div>${dodgeCritsAllowed&&!ctx.highVelocity?`<div class="automation-card rule-highlight"><strong>MANŒUVRE IMPROBABLE ACTIVE</strong><small>Les pions Esquive peuvent également annuler les critiques.</small></div>`:''}<div class="result-entry">${coverDice}${numberField('dodges','Esquives dépensées contre les touches',ctx.highVelocity?0:attackState.dodges,ctx.highVelocity?0:a.hit)}${dodgeCritsAllowed?numberField('dodgeCrits','Esquives dépensées contre les critiques',ctx.highVelocity?0:attackState.dodgeCrits,ctx.highVelocity?0:a.crit):''}</div>${liveResultStrip('APRÈS COUVERT ET ESQUIVES',c)}${rulesPanel()}`}
function defenseScreen(){const {a,d,p,lethal,guardian,pierceX,pierceImmune,dodgesUsed,blockActive,defenseSurge,result}=defenseResult(),covered=afterCover(),ranged=attackType()==='ranged',hadResult=attackResults().hit+attackResults().crit>0,suppressive=activeAttackTags().some(x=>x.def.id==='suppressif'),overwhelm=activeAttackTags().some(x=>x.def.id==='debordement'),overwhelmActive=overwhelm&&attackState.aims>0,suppression=engine.suppressionTokens({ranged,hadAttackResult:hadResult,suppressive,overwhelm,aimSpent:attackState.aims>0,vehicle:isVehicle(defender)}),ionX=attackKeywordValue('ion-x'),ion=result.wounds>0&&attackState.ionEligible?ionX:0,agile=keywordValue(defender,'agile')>0&&dodgesUsed>0,lucky=engine.defenseRerollCapacity(keywordValue(defender,'coup-de-chance-x'));return `<div class="result-strip"><b>À DÉFENDRE</b><b>${diceIcon('hit','large')} ${a.hit}</b><b>${diceIcon('crit','large')} ${a.crit}</b></div><h2>5. Défense et bilan</h2>${defensePoolView(a.hit+a.crit)}<p class="step-help">Lancez ${a.hit+a.crit} dé(s) de défense. La conversion et Perforant sont appliqués automatiquement, avec respect d’Immunité : Perforant.</p>${blockActive?`<div class="automation-card rule-highlight"><strong>BLOCAGE ACTIF</strong><small>${dodgesUsed} pion(s) Esquive effectivement dépensé(s) : ${diceIcon('defenseSurge')} devient ${diceIcon('block')} pour cette défense.</small></div>`:''}${guardian.impervious?`<div class="automation-card rule-highlight"><strong>INSENSIBLE : PERFORANT ${guardian.printedPierce} → ${guardian.pierceTotal}</strong><small>La valeur totale de Perforant de cette réserve est automatiquement réduite de 1, avant son utilisation contre Gardien puis contre le défenseur.</small></div>`:''}${lucky?`<div class="automation-card rule-highlight"><strong>COUP DE CHANCE ${lucky} : JUSQU’À ${lucky} RELANCE(S)</strong><small>Saisissez ci-dessous le résultat final après l’unique relance simultanée autorisée.</small></div>`:''}${overwhelmActive?`<div class="automation-card rule-highlight"><strong>DÉBORDEMENT : +1 SUPPRESSION</strong><small>Un pion Viser a été dépensé pendant les relances ; cette suppression s’ajoute à la suppression normale et à Suppressif.</small></div>`:''}${inputWarning()}<div class="result-entry">${lucky?numberField('defenseRerolled','Dés de défense effectivement relancés',attackState.defenseRerolled,lucky):''}${numberField('defBlock',`${diceIcon('block')} Blocages`,d.block,a.hit+a.crit)}${numberField('defSurge',`${diceIcon('defenseSurge')} Adrénalines`,d.surge,a.hit+a.crit)}${numberField('defBlank','Vierges',d.blank,a.hit+a.crit)}</div>${liveDefenseStrip(result)}<div class="conversion-note">Conversion effective : ${surgeResult('defense',defenseSurge)}<small>${pierceImmune?'Immunité : Perforant active.':`Perforant disponible : ${pierceX}${lethal.lethalUsed?` (dont ${lethal.lethalUsed} obtenu par Létal)`:''}.`}</small></div><div class="automation-card rule-highlight"><strong>PERFORANT APPLIQUÉ AUTOMATIQUEMENT : ${result.pierceUsed}</strong><small>${pierceImmune?'Aucun blocage annulé grâce à Immunité : Perforant.':`${result.pierceUsed} blocage(s) obtenu(s) sont annulé(s). Ils ne protègent donc plus contre les résultats d’attaque et ${result.wounds} blessure(s) traversent la défense.`}</small></div>${agile?`<div class="automation-card rule-highlight"><strong>AGILE : GAGNEZ 1 PION ESQUIVE</strong><small>Effet de fin d’attaque déclenché, car au moins un pion Esquive a été dépensé pendant cette défense.</small></div>`:''}<div class="resolution-log"><strong>JOURNAL DE RÉSOLUTION</strong><ol><li>Après conversion : ${attackResults().hit} touches · ${attackResults().crit} critiques</li><li>Couvert ${covered.coverCancelled}, Esquive ${covered.dodgesUsed} : ${covered.hit} touches · ${covered.crit} critiques</li><li>Impact ${modifiedResults().impactUsed}, Armure ${modifiedResults().armorCancelled} : ${a.hit} touches · ${a.crit} critiques</li><li>${result.converted} blocages obtenus ; Perforant annule automatiquement ${result.pierceUsed} blocage(s) : ${result.blocks} blocage(s) conservé(s)</li></ol></div><div class="total"><span>BLESSURES À APPLIQUER</span><strong data-live-total-wounds>${result.wounds}</strong><small>Suppression à attribuer : ${suppression}. Le défenseur vaincu n’en reçoit pas.</small>${ionX?`<small>Pions Ionique à attribuer : ${ion}${attackState.ionEligible?'':' (cible non confirmée véhicule/droïde)'}</small>`:''}</div>${rulesPanel()}`}
function showMixedWarning(){if(attackType()!=='mixed'||attackState.mixedWarningDismissed)return;const dialog=document.createElement('dialog');dialog.className='warning-dialog';dialog.innerHTML='<div class="warning-icon" aria-hidden="true">⚠</div><strong>Réserve d’attaque invalide</strong><p>Une arme de corps-à-corps ne peut pas être ajoutée à la même réserve qu’une arme à distance.</p><button type="button">J’ai compris</button>';document.body.append(dialog);dialog.oncancel=e=>e.preventDefault();dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>{attackState.mixedWarningDismissed=true;dialog.remove()};dialog.showModal()}
function stepIssue(){
  if(attackStep===0){if(attackState.range==null)return 'Sélectionnez la portée mesurée.';if(!selectedWeaponRows().length)return 'Sélectionnez au moins une arme éligible.';if(attackType()==='mixed')return 'Séparez les armes de corps-à-corps et les armes à distance.'}
  if(attackStep===1){const p=pool(),rolled=Object.values(attackState.roll).reduce((n,v)=>n+(Number(v)||0),0),expected=p.rouge+p.noir+p.blanc;if(!p.variable&&rolled!==expected)return `Le jet saisi contient ${rolled} dés, mais la réserve en contient ${expected}.`;const max=engine.rerollCapacity(attackState.aims,attackKeywordValue('precis-x'));if(attackState.rerolled>max)return `Précis et les pions Viser autorisent au maximum ${max} relances.`}
  if(attackStep===3&&attackState.guardianEligible&&attackState.guardianHits>0){const rolled=Object.values(attackState.guardianDefense).reduce((n,v)=>n+(Number(v)||0),0);if(rolled!==attackState.guardianHits)return `Le Gardien doit saisir exactement ${attackState.guardianHits} résultat(s) de défense.`}
  if(attackStep===4){const a=afterCover(),rolled=Object.values(attackState.defense).reduce((n,v)=>n+(Number(v)||0),0),expected=a.hit+a.crit,lucky=engine.defenseRerollCapacity(keywordValue(defender,'coup-de-chance-x'));if(attackState.defenseRerolled>lucky)return `Coup de Chance ${lucky} autorise au maximum ${lucky} relance(s).`;if(rolled!==expected)return `Le jet de défense saisi contient ${rolled} dé(s), mais ${expected} doivent être lancés.`}
  return null
}
function preDefenseSummary(){return''}
function decorateWeaponVerification(){if(attackStep!==0)return;const cards=[attacker.unit.name,...(attacker.unit.upgrades||[]).map(upgrade=>upgrade.name)],rows=cards.flatMap(card=>(profileFor(card)?.weapons||[]).map((weapon,index)=>({weapon,key:`${norm(card)}:${index}`})));root.querySelectorAll('.weapon-toggle[data-key]').forEach(button=>{const row=rows.find(candidate=>candidate.key===button.dataset.key),copy=button.querySelector('.weapon-copy');if(!row||!copy)return;const badge=document.createElement('em');badge.className=`data-verification ${row.weapon.verifiedAgainstCard?'verified':'unverified'}`;badge.textContent=row.weapon.verifiedAgainstCard?'✓ Dés vérifiés sur la carte':'⚠ Couleur non encore certifiée';badge.title=row.weapon.verificationSource||'Ce profil doit encore être comparé visuellement à sa carte source.';copy.append(badge)})}
function decorateResolveScreen(){decorateWeaponVerification();root.querySelectorAll('[data-collapse-side]').forEach(button=>button.onclick=()=>{collapsedSides[button.dataset.collapseSide]=!collapsedSides[button.dataset.collapseSide];resolveScreen()});const target=root.querySelector('.resolve-center .result-entry');if(target&&(attackStep===1||attackStep===4)){const progress=document.createElement('div');progress.innerHTML=entryProgress(attackStep===1?'attack':'defense');target.before(progress.firstElementChild)}}
function compactStepContent(html){return html.replace(/<h2>\d+\.[\s\S]*?<\/h2>/,'').replace(/<p class="step-help">[\s\S]*?<\/p>/,'')}
function casualtyResult(entry,newWounds){const stats=certifiedUnitStats(entry);if(!stats)return null;let remaining=Math.max(0,attackState.currentWounds);const models=stats.models.map(model=>{const wounds=Math.min(model.maxWounds,remaining);remaining-=wounds;return {...model,wounds}});return engine.allocateWounds(models,newWounds)}
